-- ============================================================
-- Carga del presupuesto de MATERIALES (hoja S2) de ARMANDO AGUILAR RESIDENCE
-- Requiere la migración 151. Reemplaza lo que hubiera cargado antes.
-- Se omiten las líneas ELIMINADAS / EXCLUIDAS (costo $0).
-- Cada material queda ligado a su división (proceso) para calcular cuándo comprar.
-- ============================================================
DO $$
DECLARE
  v_proy UUID;
  v_n INT;
BEGIN
  SELECT COUNT(*) INTO v_n FROM proyectos WHERE nombre ILIKE '%aguilar%';
  IF v_n <> 1 THEN
    RAISE EXCEPTION 'Se esperaba 1 proyecto con "Aguilar" en el nombre y hay %', v_n;
  END IF;
  SELECT id INTO v_proy FROM proyectos WHERE nombre ILIKE '%aguilar%';

  UPDATE costos_reales SET material_presupuestado_id = NULL, material_sugerido = FALSE
  WHERE proyecto_id = v_proy AND material_presupuestado_id IS NOT NULL;
  DELETE FROM materiales_presupuestados WHERE proyecto_id = v_proy;

  INSERT INTO materiales_presupuestados
    (proyecto_id, proceso_id, seccion, codigo, descripcion, unidad, cantidad_neta, desperdicio_pct,
     cantidad_total, precio_unitario, costo_sin_tax, costo_total, estado_plano, proveedor, dias_anticipacion, orden)
  SELECT v_proy, p.id, v.seccion, v.codigo, v.descripcion, v.unidad, v.neta, v.desp,
