-- Verificación: total debe ser 232835.88 y ningún material sin división
SELECT COUNT(*) AS materiales,
       ROUND(SUM(costo_total), 2) AS total_con_tax,
       COUNT(*) FILTER (WHERE proceso_id IS NULL) AS sin_division
FROM materiales_presupuestados m JOIN proyectos p ON p.id = m.proyecto_id
WHERE p.nombre ILIKE '%aguilar%';
